/* VNMY — встроенные вселенные и новеллы для открытия с диска (file://).
 * Не правим руками: npm run build
 */
window.__VNMY_BUILTIN_LIBRARY__ = {"schema":2,"universes":[{"schema":1,"id":"silent-rails","title":"Тихие пути","author":"VNMY demo","description":"Ночные платформы, поздние поезда и разговоры, которые случаются, когда все уже дома.","cover":"cover.webp","accent":"#8fb8d8","order":1,"baseUrl":"","novels":[{"schema":1,"id":"story_last_train","title":"Последний поезд","author":"VNMY demo","description":"Ночь, дождь, отменённый поезд — и девушка, которая тоже никуда не спешит. Короткая история о случайном разговоре.","cover":"assets/bg-platform-night.webp","accent":"#e0b072","universe":"silent-rails","characters":[{"id":"anya","name":"Аня","color":"#e8c08a","sprites":{"neutral":"assets/anya-neutral.webp","smile":"assets/anya-smile.webp"}},{"id":"mark","name":"Марк","color":"#a8c4d8","sprites":{"neutral":"assets/mark-neutral.webp","smile":"assets/mark-smile.webp"}}],"scenes":[{"id":"sc_platform","name":"Платформа","bg":"assets/bg-platform-night.webp","weather":"rain","cast":[{"char":"anya","sprite":"neutral","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"02:14. Дождь идёт ровно, как метроном. Последний поезд отменили полчаса назад."},{"id":"t2","speaker":null,"text":"Я остался из упрямства. И ещё потому, что девушка под фонарём тоже не уходила."},{"id":"t3","speaker":"anya","text":"Вы тоже ждёте поезд, которого не будет?"},{"id":"t4","speaker":null,"text":"","choices":[{"text":"«Вообще-то я просто не хочу домой»","goto":"sc_platform:t5"},{"text":"«Да. Из принципа»","goto":"sc_platform:t7"}]},{"id":"t5","speaker":"anya","spriteOverride":"smile","text":"О. Это лучший ответ из всех, что я слышала за сегодня.","mood":"blush","set":[{"var":"sympathy","op":"add","value":1}]},{"id":"t6","speaker":null,"text":"Она улыбнулась так, будто мы уже были знакомы. И кивнула на пустые пути.","goto":"sc_platform:t9"},{"id":"t7","speaker":"anya","text":"Из принципа — это по-нашему."},{"id":"t8","speaker":null,"text":"Она поправила стакан с кофе и не стала спрашивать больше ничего.","goto":"sc_platform:t9"},{"id":"t9","speaker":"anya","text":"Меня зовут Аня. Если поезда нет, можно хотя бы придумать, куда он ехал."},{"id":"t10","speaker":null,"text":"","choices":[{"text":"«В город, где всегда три часа ночи»","goto":"sc_platform:t11"},{"text":"«К морю, чтобы дождь стал волнами»","goto":"sc_platform:t13"}]},{"id":"t11","speaker":"anya","spriteOverride":"smile","text":"Тогда нам точно по пути. У меня там как раз нет ни одной причины оставаться.","set":[{"var":"sympathy","op":"add","value":1}]},{"id":"t12","speaker":null,"text":"Мы придумали расписание. Оно было лучше настоящего.","goto":"sc_platform:t14"},{"id":"t13","speaker":"anya","spriteOverride":"smile","text":"Море. Да. Тогда дождь — это просто волны, которые забыли уйти.","mood":"zoom","set":[{"var":"sympathy","op":"add","value":1}]},{"id":"t14","speaker":null,"text":"Где-то далеко загудело. Поезд всё-таки шёл — пустой и тёплый, будто его отправили специально за нами.","goto":"sc_train:t1"}]},{"id":"sc_train","name":"Вагон","bg":"assets/bg-train.webp","weather":"none","cast":[{"char":"mark","sprite":"neutral","pos":"left","scale":0.94},{"char":"anya","sprite":"smile","pos":"right","scale":0.94}],"steps":[{"id":"t1","speaker":null,"text":"В вагоне было тепло и пусто. Только парень у окна: наушники, стакан чая и вид человека, который едет домой третьи сутки."},{"id":"t2","speaker":"mark","text":"Предупреждаю сразу: я не проверяю билеты и не хочу знакомиться."},{"id":"t3","speaker":"anya","text":"Поздно. Мы уже.","mood":"shake"},{"id":"t4","speaker":"mark","spriteOverride":"smile","text":"Ладно. Тогда я Марк. И термос я вам всё равно не отдам."},{"id":"t9","speaker":"mark","spriteOverride":"smile","if":"sympathy >= 2","text":"Вы знакомы час, а смотритесь как люди с общей историей. Я, пожалуй, пересяду."},{"id":"t5","speaker":null,"text":"Дождь стучал по стеклу. Аня рисовала на запотевшем окне город, которого не было на картах."},{"id":"t6","speaker":"anya","text":"Марк, а ты куда едешь?"},{"id":"t7","speaker":"mark","text":"Домой. Уже третью ночь подряд."},{"id":"t8","speaker":null,"text":"Он сказал это так, что стало ясно: дома его никто не ждёт. Аня не стала уточнять. Просто подвинулась и освободила место у окна.","pause":300,"goto":"sc_kitchen:t1"}]},{"id":"sc_kitchen","name":"Кухня","bg":"assets/bg-kitchen.webp","weather":"rain","cast":[{"char":"anya","sprite":"smile","pos":"center","scale":0.96}],"steps":[{"id":"t1","speaker":null,"text":"Через месяц я стоял на её кухне и ждал, когда закипит чайник. За окном шёл тот же дождь — как будто мы его так и не выключили."},{"id":"t2","speaker":"anya","text":"Ты помнишь, что мы обещали друг другу в том поезде?"},{"id":"t3","speaker":null,"text":"","choices":[{"text":"«Что будем придумывать города»","goto":"sc_kitchen:t4"},{"text":"«Что больше не будем ждать поездов»","goto":"sc_kitchen:t6"},{"text":"«Что ты больше не одна»","goto":"sc_kitchen:t9","if":"sympathy >= 2"}]},{"id":"t4","speaker":"anya","spriteOverride":"neutral","text":"Правильно. Так вот: я нашла ещё один. Он называется никак — его ещё не построили."},{"id":"t5","speaker":null,"text":"Она поставила передо мной чашку. На ней не было ничего написано, и это было самое честное, что я держал в руках за год.","goto":"sc_kitchen:t8"},{"id":"t6","speaker":"anya","spriteOverride":"neutral","text":"Я тоже так думала. Потом поняла: ждать поездов — это и есть наш город."},{"id":"t7","speaker":null,"text":"Чайник щёлкнул. В окне отражались два человека, которые ещё не решили, кем будут друг другу.","goto":"sc_kitchen:t8"},{"id":"t8","speaker":"anya","spriteOverride":"smile","text":"Пойдём на платформу? Сегодня обещали дождь до утра.","goto":"sc_dawn:t1","gotoIf":[{"when":"sympathy >= 3","goto":"sc_dawn:t9"}]},{"id":"t9","speaker":"anya","spriteOverride":"smile","text":"Это ты придумал только что. Значит, тоже считается.","set":[{"var":"sympathy","op":"add","value":1}],"goto":"sc_kitchen:t8"}]},{"id":"sc_dawn","name":"Рассвет","bg":"assets/bg-dawn.webp","weather":"petals","cast":[{"char":"anya","sprite":"smile","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"Рассвет был мокрым и розовым. Поезд пришёл точно по расписанию — впервые за всё время."},{"id":"t2","speaker":"anya","text":"Ну вот. И что теперь?"},{"id":"t3","speaker":null,"text":"","choices":[{"text":"Взять её за руку","goto":"sc_dawn:t4"},{"text":"Отпустить и уехать","goto":"sc_dawn:t6"}]},{"id":"t4","speaker":null,"text":"Ладонь у неё была холодная, как поручень в тамбуре. Никто из нас не отпустил.","mood":"flash","set":[{"var":"took_hand","op":"set","value":true}]},{"id":"t8","if":"sympathy >= 2","text":"За вечер я насчитал {sympathy} поводов остаться. Все они были здесь, в этой руке."},{"id":"t5","speaker":"anya","text":"Значит, едем. В город, которого нет. — И улыбнулась, как тогда, под фонарём.","end":true,"endTitle":"КОНЕЦ · Тот же поезд"},{"id":"t6","speaker":null,"text":"Я сел в вагон и смотрел, как она уменьшается в окне. Она не махала — просто стояла, будто знала, что мы ещё встретимся."},{"id":"t7","speaker":"anya","text":"До следующего дождя.","end":true,"endTitle":"КОНЕЦ · До следующего дождя"},{"id":"t9","text":"Мы дошли до платформы молча — так, как умеют только те, кому уже нечего объяснять.","goto":"sc_dawn:t1"}]}],"vars":[{"name":"sympathy","type":"number","initial":0},{"name":"took_hand","type":"bool","initial":false}],"baseUrl":"stories/silent-rails/novels/last-train/","_builtin":"silent-rails/novels/last-train"}]},{"schema":1,"id":"peresylka","title":"Пересылка","author":"VNMY","description":"Тюмень, наши дни. Квартиры, куда попадают те, кто в своём мире оказался между: на волоске, в разломе, на последнем вздохе.","cover":"cover.webp","accent":"#8fb8d8","order":3,"baseUrl":"","novels":[{"schema":1,"id":"story_kto_to_ostanetsya","title":"Кто-то останется","author":"VNMY","description":"Шесть девушек из чужих миров — без своих сил, в костюмах, которые здесь выглядят как косплей. Одна бабушкина квартира на Мельникайте, недельный быт, который устроил новоявленный комендант, и правило: шов закрывает только тот, кто останется навсегда.","cover":"assets/night.webp","accent":"#8fb8d8","universe":"peresylka","vars":[{"name":"имя","type":"text","initial":""},{"name":"порог_гвен","type":"number","initial":0},{"name":"порог_фелиция","type":"number","initial":0},{"name":"порог_микаса","type":"number","initial":0},{"name":"порог_энни","type":"number","initial":0},{"name":"порог_сакура","type":"number","initial":0},{"name":"порог_тентен","type":"number","initial":0},{"name":"быт_гвен","type":"number","initial":0},{"name":"быт_микаса","type":"number","initial":0},{"name":"быт_сакура","type":"number","initial":0},{"name":"быт_энни","type":"number","initial":0},{"name":"быт_фелиция","type":"number","initial":0},{"name":"быт_тентен","type":"number","initial":0},{"name":"порядок","type":"number","initial":0}],"characters":[{"id":"hero","name":"{имя}","color":"#a8c4d8","sprites":{}},{"id":"gwen","name":"Гвен","color":"#e8a0c8","sprites":{}},{"id":"sakura","name":"Сакура","color":"#f0a878","sprites":{}},{"id":"mikasa","name":"Микаса","color":"#d98a8a","sprites":{}},{"id":"tenten","name":"Тентен","color":"#d8a25e","sprites":{}},{"id":"annie","name":"Энни","color":"#9fb8d6","sprites":{}},{"id":"felicia","name":"Фелиция","color":"#c8b6e8","sprites":{}}],"scenes":[{"id":"sc_night","name":"Ночь вселения","bg":"assets/night.webp","weather":"rain","cast":[],"steps":[{"speaker":null,"text":"02:40. Тюмень. Квартира на Мельникайте, пятый этаж, бабушкина.","id":"t1"},{"speaker":null,"text":"","ask":{"var":"имя","label":"Как тебя зовут?","placeholder":"имя","value":"Гость"},"id":"t2"},{"speaker":"hero","text":"— {имя}. Это я. — Я сказал это в темноту, чтобы хоть кто-нибудь в этом городе знал, как меня зовут.","id":"t3"},{"speaker":null,"text":"Полгода назад умерла бабушка. С тех пор я живу здесь один: первый курс, доставка, один диван и шесть чашек, которыми никто не пользуется.","id":"t4"},{"speaker":null,"text":"Я вышел в коридор и включил свет.","id":"t5"},{"speaker":null,"text":"На кухне стояла девушка в бежевой куртке, белой рубашке и красном шарфе, замотанном дважды. В руке — нож. И держала она его так, будто это не нож, а продолжение руки.","id":"t6"},{"speaker":"mikasa","text":"— Не подходи.","id":"t7"},{"speaker":"hero","text":"— Ты в моей квартире.","id":"t8"},{"speaker":"mikasa","text":"— Знаю. Это не делает ситуацию лучше.","id":"t9"},{"speaker":null,"text":"В ванной плескалось. На шкафу в коридоре сидела девушка в чёрно-белом комбинезоне и болтала ногами.","id":"t10"},{"speaker":"gwen","text":"— О, привет. Не пугайся, я обычно не на шкафу. Просто у вас мало стульев.","id":"t11"},{"speaker":"hero","text":"— ...Сколько вас?","id":"t12"},{"speaker":"gwen","text":"— Шесть. Со мной. И, кстати, я Гвен.","id":"t13"},{"speaker":null,"text":"Из шкафа выбралась девушка в красно-розовом и с повязкой на лбу. Из-за шкафа — светловолосая, в белой толстовке, с абсолютно пустым лицом. С балкона заглянула ещё одна: беловолосая, в зелёно-красной куртке, очень довольная.","id":"t14"},{"speaker":"sakura","text":"— ТАК! Где я?! Кто вы?! И где, чёрт возьми, НАРУТО?!","id":"t15"},{"speaker":"annie","text":"— Тише. Голова болит.","id":"t16"},{"speaker":"felicia","text":"— А мне нравится. Мальчик, у тебя есть что-нибудь поесть? И что-нибудь дорогое?","id":"t17"},{"speaker":null,"text":"Шестая стояла в дверях и молчала. Розово-зелёная куртка, на поясе — свиток, за спиной — что-то вроде короткого копья.","id":"t18"},{"speaker":"tenten","text":"— Их шесть. Все живые. Уже лучше, чем было.","id":"t19"},{"speaker":"hero","text":"— Так. По порядку. Кто вы?","id":"t20"},{"speaker":"gwen","text":"— Гвен Стейси. Земля-шестьдесят пять. Судя по всему, я только что переехала.","id":"t21"},{"speaker":"sakura","text":"— Сакура Харуно. Медик. Ниндзя. Ну, почти ниндзя.","id":"t22"},{"speaker":"mikasa","text":"— Микаса Аккерман.","id":"t23"},{"speaker":"annie","text":"— Энни Леонхарт. И я это обсуждать не собираюсь.","id":"t24"},{"speaker":"tenten","text":"— Тентен. Просто Тентен.","id":"t25"},{"speaker":"felicia","text":"— Фелиция Харди. Можно просто Фелиция. Или «та, которая не заплатит за такси».","id":"t26"},{"speaker":null,"text":"Я посмотрел на них ещё раз. Не в пижамах, не в чём попало: костюмы сшитые, с деталями, с ремнями и застёжками. Красный шарф, комбинезон с пауком на груди, повязка ниндзя, белая толстовка, зелёно-красная куртка с высоким воротом.","id":"t26a"},{"speaker":"hero","text":"— Так. — Я выдохнул. — Это косплей. Ролевая игра. У нас в подъезде снимают тикток?","id":"t26b"},{"speaker":"gwen","text":"— Что такое тикток?","id":"t26c"},{"speaker":"hero","text":"— Неважно. Где камера? И кто вас сюда пустил?","id":"t26d"},{"speaker":null,"text":"Я обошёл квартиру: коридор, кухня, ванная, шкаф. Камеры не было. За окном был обычный двор, обычный снег и обычная «Пятёрочка» напротив.","id":"t26e"},{"speaker":"mikasa","text":"— Это не костюмы.","id":"t26f"},{"speaker":"hero","text":"— Ну конечно.","id":"t26g"},{"speaker":null,"text":"Тогда Сакура решила доказать. Она сложила пальцы в странную фигуру, сказала слово — и ничего не произошло. Гвен подпрыгнула к стене, чтобы залезть на неё, и просто съехала по обоям. Энни сжала кулак, будто ждала, что рука покроется льдом. Рука не покрылась.","id":"t26h"},{"speaker":"sakura","text":"— …У меня не получается.","id":"t26i"},{"speaker":"annie","text":"— У меня тоже.","id":"t26j"},{"speaker":null,"text":"Шесть девчонок в костюмах стояли в моей прихожей, мёрзли и были совершенно обычными. Я всё ещё думал, что это розыгрыш. Просто очень дорогой и очень странный.","id":"t26k"},{"speaker":"mikasa","text":"— Мы без силы. Совсем.","id":"t26l"},{"speaker":null,"text":"Минусы были везде. Их нельзя было развести на пару, они не могли открыть окно, потому что «там нет опоры», и они не умели пользоваться краном, который не грелся сам.","id":"t26lc1"},{"speaker":"felicia","text":"— И что нам теперь делать? — Фелиция спросила это у меня, и мне это не понравилось.","id":"t26lc2"},{"speaker":"hero","text":"— Жить по-моему. Иначе я вас не разберу.","id":"t26lc3"},{"speaker":null,"text":"Я стоял в трусах и жёлтой футболке с логотипом доставки, в квартире, где только что стало на шесть человек больше.","id":"t27"},{"speaker":"hero","text":"— У меня один диван.","id":"t28"},{"speaker":"gwen","text":"— Насчёт дивана не переживай. Я и на шкафу могу.","id":"t29"},{"speaker":null,"text":"За спиной тихо щёлкнул бабушкин сервант. Я знал этот звук: так открывается ящик, который бабушка называла «потеряшки».","id":"t30"},{"speaker":null,"text":"В ящике лежала тетрадь. Бабушкин почерк, первая страница: «Если ты это читаешь — значит, я не успела тебя научить. Садись. Это надолго.»","id":"t31"}]},{"id":"sc_morning","name":"Шесть зубных щёток","bg":"assets/kitchen.webp","weather":"none","cast":[],"steps":[{"speaker":null,"text":"Утро началось с очереди в ванную. Восемь минут. Шесть человек. Один кран.","id":"t1"},{"speaker":null,"text":"Спали они в чём пришли: Микаса — в куртке, Сакура — на кухонном полу, Энни — в толстовке с капюшоном, Гвен — на шкафу.","id":"t1a"},{"speaker":"felicia","text":"— Мальчик, у тебя есть запасной халат? Желательно шёлковый.","id":"t2"},{"speaker":"hero","text":"— У меня есть бабушкин. Он в цветах.","id":"t3"},{"speaker":"felicia","text":"— Беру.","id":"t4"},{"speaker":null,"text":"Энни сидела на полу и ела мороженое. В девять утра. Из большой ложки.","id":"t5"},{"speaker":"hero","text":"— Ты в порядке?","id":"t6"},{"speaker":"annie","text":"— Лучше, чем обычно. Тут не стреляют.","id":"t7"},{"speaker":null,"text":"Сакура разбирала мой холодильник так, будто это поле боя.","id":"t8"},{"speaker":"sakura","text":"— Молоко, три яйца, огурец и... это что?","id":"t9"},{"speaker":"hero","text":"— Соус. Наверное.","id":"t10"},{"speaker":"sakura","text":"— Это не соус. Это преступление.","id":"t11"},{"speaker":null,"text":"Микаса стояла у окна. Снег шёл, и город был белый до горизонта.","id":"t12"},{"speaker":"mikasa","text":"— Здесь много снега.","id":"t13"},{"speaker":"hero","text":"— Это Тюмень. У нас много снега.","id":"t14"},{"speaker":"mikasa","text":"— У нас тоже. До крыш.","id":"t15"},{"speaker":null,"text":"Я стоял посреди кухни и думал, чем помочь. Один раз, по-настоящему.","choices":[{"text":"Отдать Микасе свою куртку","goto":"sc_morning:t17"},{"text":"Помочь Сакуре на кухне","goto":"sc_morning:t18"},{"text":"Спросить Гвен, как она сюда попала","goto":"sc_morning:t19"}],"goto":"sc_morning:t20","id":"t16"},{"speaker":null,"text":"Она посмотрела на куртку, потом на меня.","goto":"sc_morning:t17a","id":"t17"},{"speaker":"mikasa","text":"— Тебе будет холодно.","goto":"sc_morning:t17b","id":"t17a"},{"speaker":"hero","text":"— Я на работе.","goto":"sc_morning:t17c","id":"t17b"},{"speaker":"mikasa","text":"— Это не ответ.","goto":"sc_morning:t17d","id":"t17c"},{"speaker":null,"text":"Но куртку она взяла. И не сняла до вечера.","goto":"sc_morning:t20","id":"t17d"},{"speaker":"hero","text":"— Давай помогу.","goto":"sc_morning:t18a","id":"t18"},{"speaker":null,"text":"Я взял нож и порезал лук так, как учила бабушка: мелко, ровно, не глядя.","goto":"sc_morning:t18b","id":"t18a"},{"speaker":"sakura","text":"— Ты умеешь.","goto":"sc_morning:t18c","id":"t18b"},{"speaker":"hero","text":"— Я умею плакать. Это тоже нужно.","id":"t18c"},{"speaker":"hero","text":"— Как ты сюда попала?","goto":"sc_morning:t19a","id":"t19"},{"speaker":"gwen","text":"— Через дверь. — Гвен пожала плечами. — Просто не ту.","goto":"sc_morning:t19b","id":"t19a"},{"speaker":"hero","text":"— А какая была та?","goto":"sc_morning:t19c","id":"t19b"},{"speaker":"gwen","text":"— Моя. — Она улыбнулась. — Пока.","id":"t19c"},{"speaker":null,"text":"К полудню стало ясно: они не исчезнут. И ещё кое-что.","id":"t20"},{"speaker":null,"text":"Входная дверь была открыта настежь. Снаружи не было ничего: серая муть, как засвеченная плёнка.","id":"t21"},{"speaker":"gwen","text":"— Шов. Я видела такое один раз. Повторять не хочу.","id":"t22"},{"speaker":null,"text":"Я закрыл дверь. Никто не спросил, что там. Все и так поняли.","id":"t23"},{"speaker":"hero","text":"— Так. — Я сел на кухню с блокнотом. — Шесть имён. По алфавиту. Аккерман, Леонхарт, Стейси, Харуно, Харди, Тентен.","id":"t23c1"},{"speaker":"mikasa","text":"— Ты нас записываешь?","id":"t23c2"},{"speaker":"hero","text":"— Я вас учитываю. Это разные вещи.","id":"t23c3"},{"speaker":null,"text":"Я не верил, что список что-то решит. Это было единственное, что я умел: разложить по полочкам то, чего я не понимал.","id":"t23c4"},{"speaker":"tenten","text":"— Значит, порог с той стороны. Пока он открыт, мы не можем уйти.","id":"t24"},{"speaker":"hero","text":"— Сначала одеться. Потом — тетрадь.","id":"t25"}]},{"id":"sc_clothes","name":"Мой гардероб","bg":"assets/hall.webp","weather":"none","cast":[],"steps":[{"speaker":null,"text":"К девяти утра стало ясно: в своих костюмах они дальше подъезда не уйдут. Не потому что странно. Потому что минус двенадцать.","id":"t1","goto":"sc_clothes:t2"},{"speaker":"felicia","text":"— Мальчик, у тебя есть что-нибудь… не с пауком?","id":"t2","goto":"sc_clothes:t3"},{"speaker":"hero","text":"— Есть бабушкин халат.","id":"t3","goto":"sc_clothes:t4"},{"speaker":"felicia","text":"— Беру.","id":"t4","goto":"sc_clothes:t5"},{"speaker":null,"text":"Я вывалил на диван всё, что нашлось: три футболки, две толстовки, спортивные штаны, свитер с оленем, бабушкин халат в ромашках и рубашку, которую я надевал два раза в жизни.","id":"t5","goto":"sc_clothes:t6"},{"speaker":"gwen","text":"— Это мне? — Гвен вытащила футболку с логотипом доставки. — Она мне по колено.","id":"t6","goto":"sc_clothes:t7"},{"speaker":"hero","text":"— Зато тёплая.","id":"t7","goto":"sc_clothes:t8"},{"speaker":null,"text":"Микаса надела свитер с оленем поверх своей рубашки. Рукава закрыли пальцы. Она посмотрела на меня так, будто я отдал ей что-то очень дорогое.","id":"t8","goto":"sc_clothes:t9"},{"speaker":"mikasa","text":"— Он тёплый.","id":"t9","goto":"sc_clothes:t10"},{"speaker":"sakura","text":"— А мне? — Сакура уже натягивала спортивные штаны. Они были велики ей ровно на одну Сакуру.","id":"t10","goto":"sc_clothes:t11"},{"speaker":"annie","text":"— Я возьму это. — Энни забрала мою единственную чёрную толстовку и застегнула капюшон до подбородка. — Пахнет кофе. Я не против.","id":"t11","goto":"sc_clothes:t12"},{"speaker":null,"text":"Тентен подвязала мою рубашку узлом на поясе, посмотрела в зеркало и осталась довольна. Гвен легла на диван и объявила, что теперь она домашняя.","id":"t12","goto":"sc_clothes:t13"},{"speaker":"gwen","text":"— Домашняя. Не путать с «домашний арест».","id":"t13","goto":"sc_clothes:t14"},{"speaker":null,"text":"Фелиция вышла в бабушкином халате и моей шапке. В этом было столько достоинства, что никто не засмеялся.","id":"t14","goto":"sc_clothes:t15"},{"speaker":"felicia","text":"— Шёлк был бы лучше. Но сойдёт.","id":"t15","goto":"sc_clothes:t15a"},{"speaker":null,"text":"Свои костюмы они сложили стопкой на стиральной машине: аккуратно, как складывают форму. Микаса положила сверху шарф.","id":"t15a","goto":"sc_clothes:t15ac1"},{"speaker":"hero","text":"— Я подпишу. Скотчем. Чтобы не путались.","id":"t15ac1"},{"speaker":"annie","text":"— Подпиши. Так спокойнее.","id":"t15ac2"},{"speaker":null,"text":"Я наклеил на каждую стопку кусочек малярного скотча с именем. Это было глупо, и это сразу сработало: вещи перестали быть общими.","id":"t15ac3"},{"speaker":"hero","text":"— В магазин пойдём в этом. — Я запнулся. — Просто…","id":"t16","goto":"sc_clothes:t17"},{"speaker":"mikasa","text":"— Никто не должен понять, что мы не отсюда.","id":"t17","goto":"sc_clothes:t18"},{"speaker":null,"text":"Я кивнул. Я всегда киваю, когда нечего сказать.","id":"t18"}]},{"id":"sc_bath","name":"Очередь в ванную","bg":"assets/bath.webp","weather":"none","cast":[],"steps":[{"speaker":null,"text":"В восемь ноль ноль я понял, что в квартире одна ванная, шесть девушек и ни одного плана.","id":"t1"},{"speaker":"gwen","text":"— Я первая. Я вообще встаю раньше всех.","id":"t2"},{"speaker":"hero","text":"— Ты встала в четыре и ходила по кухне.","id":"t3"},{"speaker":"gwen","text":"— Это называлось «думать».","id":"t4"},{"speaker":null,"text":"Полотенец было три. Крючков — два. Полка над раковиной одна, и на ней уже стояло восемь баночек, из которых две были мои.","id":"t5"},{"speaker":"annie","text":"— Я постою. — Энни села на край ванны с полотенцем на плече и весь день больше ни с кем не спорила.","id":"t6"},{"speaker":null,"text":"К обеду стало ясно, что это не быт, а логистика. Я взял маркер и лист в клетку.","id":"t7"},{"speaker":null,"text":"Так на двери ванной появился график: шесть имён, шесть времен, по двадцати минут. Седьмая строчка — моя, 23:40.","id":"t8"},{"speaker":"tenten","text":"— А это что? — Тентен прочитала вслух: «Пятая — Энни. Не отнимать. Шестая — я. Не напоминать». У неё дёрнулся уголок рта. — Мне нравится.","id":"t9"},{"speaker":"hero","text":"— Очередь. Без неё вы съедите друг друга.","id":"t10"},{"speaker":"felicia","text":"— Мальчик, у меня в замке купальню охраняли. Здесь охранять некого.","id":"t11"},{"speaker":null,"text":"Гвен помыла голову на кухне, в раковине, и сделала это так ловко, что я почувствовал себя лишним в собственном доме.","id":"t12"},{"speaker":"mikasa","text":"— У вас вода идёт сама. — Микаса держала руку под краном, пока не одёрнула. — Это неудобно. Не к чему привыкать.","id":"t13"},{"speaker":null,"text":"К вечеру сгорел фен: шесть голов за один день. Я дописал в лист: «фен. умер. причина — мы».","id":"t14"},{"speaker":"hero","text":"— Завтра сушимся на балконе.","id":"t15"},{"speaker":"sakura","text":"— В минус двенадцать? — Сакура впервые за сутки обрадовалась, что ей будет холодно.","id":"t16"},{"speaker":null,"text":"Ночью я стёр график и нарисовал новый: с колонкой «кто не помылся» и строкой «занял дольше двадцати — стучать, не ждать».","id":"t17"},{"speaker":"annie","text":"— Правильно. — Энни посмотрела и добавила третий крючок для полотенца. Он был один на шесть человек.","id":"t18"},{"speaker":null,"text":"Это была первая вещь в доме, которую я организовал. Я ещё не знал, что на этом тут всё и держится.","id":"t19"}]},{"id":"sc_street","name":"Первый выход","bg":"assets/street.webp","weather":"snow","cast":[],"steps":[{"speaker":null,"text":"На улице было минус двенадцать. Шесть девчонок в моих футболках и бабушкином халате шли за мной по Мельникайте, и никто не жаловался.","id":"t1","goto":"sc_street:t2"},{"speaker":"gwen","text":"— Тут снег хрустит. У нас он просто лежал.","id":"t2","goto":"sc_street:t3"},{"speaker":null,"text":"У «Монетки» нас встретил мужик с собакой. Он посмотрел на шесть девчонок, потом на меня. — Косплей, что ли?","id":"t3","goto":"sc_street:t4"},{"speaker":"hero","text":"— Ролевая игра. — Это было первое, что пришло в голову.","id":"t4","goto":"sc_street:t5"},{"speaker":null,"text":"— А, ну да, — кивнул он. — Молодцы. Дочке понравится.","id":"t5","goto":"sc_street:t6"},{"speaker":"sakura","text":"— Он что, нам поверил?","id":"t6","goto":"sc_street:t7"},{"speaker":"hero","text":"— Он просто вежливый.","id":"t7","goto":"sc_street:t8"},{"speaker":null,"text":"Сакура вертела головой. Энни считала вывески. Микаса проверяла, нет ли за нами хвоста. Тентен несла пакет, хотя пакет ей никто не давал.","id":"t8","goto":"sc_street:t8c1"},{"speaker":null,"text":"Я выдал каждой бумажку с адресом, номером подъезда и кодом домофона, и сказал, что если потеряемся — стоим на месте и не идём ни с кем.","id":"t8c1"},{"speaker":"felicia","text":"— Ты говоришь с нами как с классом.","id":"t8c2"},{"speaker":"hero","text":"— У меня не было времени придумать, как говорить с вами по-другому.","id":"t8c3"},{"speaker":"annie","text":"— Мороженое здесь есть?","id":"t9","goto":"sc_street:t10"},{"speaker":"hero","text":"— Зимой? Вряд ли.","id":"t10","goto":"sc_street:t11"},{"speaker":"annie","text":"— Тогда мы идём не туда.","id":"t11","goto":"sc_street:t12"},{"speaker":null,"text":"Внутри было тепло, пахло хлебом, и шесть девчонок в моих вещах замолчали — впервые за сутки.","id":"t12","goto":"sc_street:t13"},{"speaker":"gwen","text":"— Столько еды. — Она сказала это тихо. — У нас так не бывает.","id":"t13","goto":"sc_street:t14"},{"speaker":null,"text":"Сакура набрала крупы, яиц и лука. Энни — мороженое, оно там всё-таки было. Фелиция — шоколад и, непонятно как, чужие ключи; я заставил вернуть. Тентен выбрала самую дешёвую лапшу и сказала, что это интересный опыт.","id":"t14","goto":"sc_street:t15"},{"speaker":null,"text":"На кассе женщина улыбнулась: — Хорошего праздника, девчонки. — Гвен сказала «спасибо», а потом всю дорогу домой спрашивала, какой у нас праздник.","id":"t15","goto":"sc_street:t16"},{"speaker":"hero","text":"— В том и дело, что никакого.","id":"t16"}]},{"id":"sc_kitchen","name":"Кухня в шесть рук","bg":"assets/kitchen.webp","weather":"none","cast":[],"steps":[{"speaker":null,"text":"В час дня я пришёл на кухню и не узнал её.","id":"t1"},{"speaker":null,"text":"На плите стояли две кастрюли — вторую Сакура одолжила у соседки, — на столе было три доски вместо одной, а на подоконнике сушилось полотенце, которого раньше не было.","id":"t2"},{"speaker":"sakura","text":"— Мальчик, у тебя одна плита на шесть человек. Одна!","id":"t3"},{"speaker":"hero","text":"— У меня была одна плита на одного. Это другое.","id":"t4"},{"speaker":"felicia","text":"— У тебя яйца кончились на последней полке, а ты молчишь.","id":"t5"},{"speaker":"annie","text":"— Я считала. Было восемь.","id":"t6"},{"speaker":null,"text":"Я не считал. За восемь лет жизни один я никогда не считал яйца.","id":"t7"},{"speaker":null,"text":"К ужину у меня в блокноте было: что едят все, что не едят двое, и кому нужно горячее, иначе он не спит.","id":"t8"},{"speaker":"gwen","text":"— Я ем всё, кроме оливок. Из оливок делают войну.","id":"t9"},{"speaker":"tenten","text":"— Мне нужно что жевать. Мясо сушёное есть?","id":"t10"},{"speaker":"hero","text":"— Есть творог и семечки. Это не одно и то же.","id":"t11"},{"speaker":null,"text":"Фелиция разбила яйцо об край миски слишком усердно, и оно упало на пол. Она посмотрела на него и сказала, что оно было не её.","id":"t12"},{"speaker":"mikasa","text":"— Оно упало от стены. — Микаса подобрала осколок и выкинула. — Так бывает, если держать одной рукой.","id":"t13"},{"speaker":null,"text":"Тентен таскала сумки из коридора одной рукой, по три пакета, и поставила их ровно так, как я всегда мечтал, но никогда не делал.","id":"t14"},{"speaker":null,"text":"Так у нас появились чашки с именами, написанными малярным скотчем. Шестая была моя, и я повесил её на обычный крючок, отдельно.","id":"t15"},{"speaker":"hero","text":"— Правило. Готовит тот, кто дежурил. Моет тот, кто ел. Не ноет никто.","id":"t16"},{"speaker":"sakura","text":"— Кто это придумал? — Я. — Сакура прищурилась на мой список и дописала сверху жирным: «ЕДУ НЕ ПРЯТАТЬ В НОСКИ».","id":"t17"},{"speaker":"felicia","text":"— Это был самый вкусный рис в доме.","id":"t18"},{"speaker":null,"text":"Кухня стала шумной, грязной и своей. Я впервые за полгода ел не один.","id":"t19"}]},{"id":"sc_rules","name":"Правила пересылки","bg":"assets/table.webp","weather":"none","cast":[],"steps":[{"speaker":null,"text":"В тетради было шесть страниц. На каждой — по правилу, и все написаны так, будто бабушка боялась, что я не пойму.","id":"t1"},{"speaker":null,"text":"Правило первое. Тюмень стоит на пересылке. В городе есть квартиры, куда попадают те, кто в своём мире оказался между: на волоске, в разломе, на последнем вздохе.","id":"t2"},{"speaker":"gwen","text":"— То есть мы все умерли?","id":"t3"},{"speaker":"hero","text":"— Вы все почти. Разница есть.","id":"t4"},{"speaker":"annie","text":"— Утешил.","id":"t5"},{"speaker":null,"text":"Правило второе. У каждого гостя есть порог — место в этом городе, которое отвечает его миру. Через порог можно уйти домой. Провести может только смотритель.","id":"t6"},{"speaker":"mikasa","text":"— Смотритель — это ты.","id":"t7"},{"speaker":"hero","text":"— Смотритель была бабушка. Теперь, видимо, я.","id":"t8"},{"speaker":"sakura","text":"— А если мы не уйдём?","id":"t9"},{"speaker":null,"text":"Правило третье. Пока шов открыт, дом держит всех. Когда шов закроется, он закроется навсегда — и заберёт смотрителя.","id":"t10"},{"speaker":null,"text":"Правило четвёртое. Шов закрывает вахта: один гость, который останется навсегда. Добровольно.","id":"t11"},{"speaker":"felicia","text":"— Навсегда — это как? Совсем?","id":"t12"},{"speaker":null,"text":"Правило пятое. Порог возвращает гостю его силу — но только на один шаг. Оставаясь, гость платит: сила гаснет навсегда, его мир забывает его, а он забывает дорогу назад.","id":"t13"},{"speaker":"gwen","text":"— То есть сейчас мы просто девчонки. — Гвен посмотрела на свои руки. — А у порога снова станем собой.","id":"t13a","goto":"sc_rules:t14"},{"speaker":"tenten","text":"— А тот, кто уходит?","id":"t14"},{"speaker":null,"text":"Правило шестое. Уходя, гость возвращается в свой мир, в ту секунду, из которой его выдернули. Но смотритель помнит его всегда. Это единственное, что остаётся.","id":"t15"},{"speaker":null,"text":"Внизу, мелким почерком: «Не решай за них. Просто будь рядом, когда они будут решать».","id":"t16"},{"speaker":"gwen","text":"— Знаешь, что самое неприятное? Я даже не удивлена.","id":"t17"},{"speaker":"mikasa","text":"— Мы пойдём к порогам.","id":"t18"},{"speaker":"hero","text":"— Пойдём. По одному.","id":"t19"},{"speaker":"hero","text":"— Сначала правила дома. Потом — ваши.","id":"t19c1"},{"speaker":"annie","text":"— У тебя уже есть правила дома?","id":"t19c2"},{"speaker":"hero","text":"— Будут.","id":"t19c3"},{"speaker":null,"text":"Шесть порогов. Шесть девушек. Одна бабушкина квартира.","id":"t20"}]},{"id":"sc_command","name":"Комендант","bg":"assets/table.webp","weather":"none","cast":[],"steps":[{"speaker":null,"text":"После тетради я не мог уснуть два часа. Потом встал, нашёл малярный скотч, ватман и маркер.","id":"t1"},{"speaker":null,"text":"К утру в коридоре висела доска. Колонки: «кто», «спит», «ест», «не трогать», «страх». Пятая колонка была самая заполненная.","id":"t2"},{"speaker":"hero","text":"— С сегодняшнего дня живём по расписанию. Подъём в семь, тишина в двадцать три, пятиминутка каждый вечер у стола.","id":"t3"},{"speaker":"felicia","text":"— Ты чего, надзиратель?","id":"t4"},{"speaker":"hero","text":"— Смотритель. Надзирателю платят.","id":"t5"},{"speaker":null,"text":"За ужином я задал первый вопрос по форме: по тридцать секунд на каждую, не перебивая — что вы помните из последней секунды своего мира.","id":"t6"},{"speaker":"gwen","text":"— Удар. Гудки. Я думала только, что концерт через два дня.","id":"t7"},{"speaker":"mikasa","text":"— Крик. Я не добежала.","id":"t8"},{"speaker":"sakura","text":"— Дым. И что меня толкнули. Не разобрала, кто.","id":"t9"},{"speaker":"annie","text":"— Холод. И сестра. Не знаю, жива ли она.","id":"t10"},{"speaker":"felicia","text":"— Крыша. И мои монеты на столе. Я их не забрала.","id":"t11"},{"speaker":"tenten","text":"— Я не помню. И это злит меня больше всего.","id":"t12"},{"speaker":"hero","text":"— Итого: шесть миров, шесть обрывов, один дом, один адрес. Значит, дело не в вас. Дело в адресе.","id":"t13"},{"speaker":null,"text":"Я переписал всё в тетрадь в клетку и попытался свести в систему. Система не складывалась, и я сделал вид, что это ничего не меняет.","id":"t14"},{"speaker":null,"text":"Гипотез было четыре: массовый сон, утечка газа на Мельникайте, чья-то работа и бабушка. От каждой мне становилось хуже по-разному.","id":"t15"},{"speaker":null,"text":"Я проверил газ, вызвал службу, обошёл все пять подъездов и переписал номера квартир. «Вы не первый», — сказал диспетчер и зевнул.","id":"t16"},{"speaker":null,"text":"В три часа ночи я дописал на доске последнюю строку: «причины нет. есть дом».","id":"t17"},{"speaker":"annie","text":"— Ты не можешь это решить. — Энни стояла в дверях с кружкой. — Ты можешь только управлять. Так?","id":"t18"},{"speaker":"hero","text":"— Мне так спокойнее.","id":"t19"},{"speaker":null,"text":"Она кивнула и взяла маркер: напротив каждого имени в колонке «страх» поставила прочерк. «Запиши, — говорит. — Нам тоже нужно видеть, что всё учтено».","id":"t20"},{"speaker":"hero","text":"— Неделя. Живём неделю по-моему, я разбираюсь. Потом — к порогам.","id":"t21"},{"speaker":null,"text":"Шесть пар посмотрели не на меня, а на доску, на которой впервые кто-то что-то обещал.","id":"t22"},{"speaker":"gwen","text":"— Командир. — Она сказала это так, будто сама не заметила.","id":"t23"}]},{"id":"sc_adapt","name":"Неделя адаптации","bg":"assets/hall.webp","weather":"none","cast":[],"steps":[{"speaker":null,"text":"Первая неделя: шесть девчонок, одна квартира и один человек, который решил, что если он всё распишет — значит, он это контролирует.","if":"порядок == 0","goto":"sc_adapt:t2","id":"t1"},{"speaker":null,"text":"На доске {порядок} из шести галочек. Остались мелочи, которые никто не решается сделать первым.\nКого слушаем?","choices":[{"text":"Гвен: лестница, которая едет","if":"быт_гвен == 0","goto":"sc_a_gwen:t1"},{"text":"Микаса: свет и шторы","if":"быт_микаса == 0","goto":"sc_a_mikasa:t1"},{"text":"Сакура: газовая плита","if":"быт_сакура == 0","goto":"sc_a_sakura:t1"},{"text":"Энни: порядок","if":"быт_энни == 0","goto":"sc_a_annie:t1"},{"text":"Фелиция: деньги","if":"быт_фелиция == 0","goto":"sc_a_felicia:t1"},{"text":"Тентен: задания","if":"быт_тентен == 0","goto":"sc_a_tenten:t1"}],"gotoIf":[{"when":"быт_гвен >= 1 && быт_микаса >= 1 && быт_сакура >= 1 && быт_энни >= 1 && быт_фелиция >= 1 && быт_тентен >= 1","goto":"sc_sick:t1"}],"id":"t2"}],"card":false},{"id":"sc_a_gwen","name":"Лестница, которая едет","bg":"assets/street.webp","weather":"snow","cast":[],"steps":[{"speaker":null,"text":"В торговом центре Гвен встала перед эскалатором и не сдвинулась.","id":"t1"},{"speaker":"gwen","text":"— Это не страшно. Я знаю, что это не страшно.","id":"t2"},{"speaker":"hero","text":"— Тогда иди.","id":"t3"},{"speaker":null,"text":"Она поставила ногу на ленту, отдёрнула и посмотрела на меня так, будто это я был виноват.","id":"t4"},{"speaker":"gwen","text":"— Я падала с двадцатого этажа. С двадцатого, {имя}. А это едет само.","id":"t5"},{"speaker":"hero","text":"— Оно едет, потому что должно. Оно не решает.","id":"t6"},{"speaker":"gwen","text":"— Вот именно.","id":"t7"},{"speaker":null,"text":"Я записал в доску: «Гвен — не высота, а то, что она не управляет». И увидел, что написал о живом человеке как о поломке.","id":"t8"},{"speaker":"gwen","text":"— Ты нас по полочкам раскладываешь?","id":"t9"},{"speaker":"hero","text":"— Да.","id":"t10"},{"speaker":"gwen","text":"— Ну хоть не врёшь.","id":"t11"},{"speaker":null,"text":"Вечером она попросилась со мной на смену. Я сказал «нельзя» и всё равно дал ей рюкзак: четыре адреса, двор без фонарей, девять этажей пешком.","id":"t12"},{"speaker":null,"text":"Она развезла заказы за два часа, обогнала меня по лестнице и ни разу не встала на эскалатор — шла по ступеням, как по своим.","id":"t13"},{"speaker":"gwen","text":"— Девятьсот. — Она держала купюры двумя пальцами, как барабанные палочки. — Мне впервые платят.","id":"t14"},{"speaker":"hero","text":"— Не впервые. Ты играла.","id":"t15"},{"speaker":"gwen","text":"— За это не платят.","id":"t16"},{"speaker":null,"text":"Она встала на эскалатор, взялась за поручень и поехала, глядя на свои руки, — злилась, что едет, и не сходила.","id":"t17"},{"speaker":null,"text":"На доске я поставил ей первую галочку и подписал: «нужна скорость, а не риск». Она прочитала и не стала спорить.","id":"t18"},{"speaker":"hero","text":"— Завтра берёшь шесть адресов. — Я написал это в график и сразу почувствовал себя диктатором.","set":[{"var":"быт_гвен","op":"set","value":"1"},{"var":"порядок","op":"add","value":"1"}],"goto":"sc_adapt:t1","id":"t19"}]},{"id":"sc_a_mikasa","name":"Свет и шторы","bg":"assets/kitchen.webp","weather":"none","cast":[],"steps":[{"speaker":null,"text":"Микаса не выключала свет. Никогда, даже в минус двенадцать, даже в четыре утра.","id":"t1"},{"speaker":"hero","text":"— Лампочка стоит сорок рублей.","id":"t2"},{"speaker":"mikasa","text":"— Я не сплю в темноте. — Она держала чашку обеими руками. — Темнота у нас означала, что пришли.","id":"t3"},{"speaker":null,"text":"Я купил ночник. Самый дешёвый, в форме груши. Она поставила его в угол, включила и весь вечер делала вид, что не замечает.","id":"t4"},{"speaker":null,"text":"Второе, чего она не понимала, — шторы.","id":"t5"},{"speaker":"mikasa","text":"— Зачем закрывать окна изнутри? — Она спросила спокойно, и только Тентен услышала и перестала жевать.","id":"t6"},{"speaker":"hero","text":"— Соседи.","id":"t7"},{"speaker":"mikasa","text":"— Соседи — это не стена.","id":"t8"},{"speaker":null,"text":"Сахар, варенье, мёд — она ела сладкое ложками, как будто в её мире калории стоили дороже спокойствия.","id":"t9"},{"speaker":"annie","text":"— Ты мне половину отняла.","id":"t10"},{"speaker":"mikasa","text":"— Прости. — И впервые за неделю пожаловалась не на врага. — Здесь очень холодно. Я не понимаю, как это терпят.","id":"t11"},{"speaker":null,"text":"Я включил батарею на максимум и постелил на пол плед. Она села на пол, у двери, потому что сидеть ей нужно было у выхода.","id":"t12"},{"speaker":"hero","text":"— Микаса. Это не пост.","id":"t13"},{"speaker":"mikasa","text":"— Это моё место. — Она посмотрела на меня ровно, и я замолчал.","id":"t14"},{"speaker":null,"text":"Наутро у двери лежали коврик, подушка и лампа, а рядом я приклеил листок: «место Микасы. не трогать».","id":"t15"},{"speaker":"mikasa","text":"— Спасибо. — Она сказала это мне в спину, пока я делал вид, что прибиваю полку.","id":"t16"},{"speaker":null,"text":"Она спала четыре часа, а потом вставала и молча проверяла замок. Я перестал делать вид, что не слышу.","id":"t17"},{"speaker":null,"text":"В колонке «страх» напротив её имени я написал: «не боится темноты. боится, что не успеет».","set":[{"var":"быт_микаса","op":"set","value":"1"},{"var":"порядок","op":"add","value":"1"}],"goto":"sc_adapt:t1","id":"t18"}]},{"id":"sc_a_sakura","name":"Газовая плита","bg":"assets/kitchen.webp","weather":"none","cast":[],"steps":[{"speaker":null,"text":"Сакура три дня не подходила к плите. Потом я застал её у неё: она жгла клочки бумаги в раковине и смотрела, как горит.","id":"t1"},{"speaker":"hero","text":"— У меня тут пластиковые трубы.","id":"t2"},{"speaker":"sakura","text":"— Я знаю. Я держу на расстоянии. — Она потушила клочок пальцами и показала обожжённую подушечку. — Здесь огонь сам. Без меня. Это нечестно.","id":"t3"},{"speaker":null,"text":"Вечером я убрал с кухни всё, что горит, а на дверце плиты приклеил скотч с двумя словами: «Гори едой».","id":"t4"},{"speaker":"sakura","text":"— Ты мне как команду отдаёшь.","id":"t5"},{"speaker":"hero","text":"— Тебе так понятнее.","id":"t6"},{"speaker":"sakura","text":"— Понятнее. — Она швырнула скотч в корзину. Но кастрюлю поставила.","id":"t7"},{"speaker":null,"text":"На четвёртый день она готовила: рис, курица, три кастрюли, запах на весь подъезд. Фелиция приходила «пробовать» и оставалась на ужин.","id":"t8"},{"speaker":"felicia","text":"— Ещё.","id":"t9"},{"speaker":"sakura","text":"— Это на завтрак!","id":"t10"},{"speaker":null,"text":"Я подсматривал, как она ждёт, что её похвалят, и злится, что не хвалят. Тогда я написал на доске: «Повар — Сакура. Ужин — её. Не спорить».","id":"t11"},{"speaker":"sakura","text":"— Ты записал меня в повара, чтобы я не сожгла дом.","id":"t12"},{"speaker":"hero","text":"— Я записал, чтобы вас кормили. То, что не сожжёшь, — побочный эффект.","id":"t13"},{"speaker":null,"text":"Она рассмеялась. Впервые — без публики, на пустой кухне, в моей толстовке. Смех был короче, чем на сцене, и настоящий в сто раз.","id":"t14"},{"speaker":"sakura","text":"— Ладно, смотритель. Пусть будет по-твоему.","id":"t15"},{"speaker":null,"text":"С тех пор плита была её, и я к ней не подходил вообще, даже чтобы вскипятить воду.","id":"t16"},{"speaker":null,"text":"В её колонке «не трогать» я написал: «плита. и её шутки, когда ей страшно».","set":[{"var":"быт_сакура","op":"set","value":"1"},{"var":"порядок","op":"add","value":"1"}],"goto":"sc_adapt:t1","id":"t17"}]},{"id":"sc_a_annie","name":"Порядок","bg":"assets/table.webp","weather":"none","cast":[],"steps":[{"speaker":null,"text":"Энни трогала всё. Не брала — трогала: ровно ли стоят кружки, закрыта ли дверь, на месте ли мой список.","id":"t1"},{"speaker":"hero","text":"— Ты чего делаешь?","id":"t2"},{"speaker":"annie","text":"— Ты не успеваешь. — Она переложила мои блокноты по размеру. — Третьего дня ты поставил соль не туда. Я убрала.","id":"t3"},{"speaker":null,"text":"И она боялась батареи: прикладывала к ней тыльную сторону ладони, отдёргивала и прикладывала снова, как на допросе.","id":"t4"},{"speaker":"hero","text":"— Энни, она не обожжёт.","id":"t5"},{"speaker":"annie","text":"— Она горячая. Значит, может. Это не страх, это факт.","id":"t6"},{"speaker":null,"text":"Я надел на батарею чехол из картона и подписал: «тёплая, но не злая». Она не подходила неделю. Потом прислонила спиной и уснула на полу кухни.","id":"t7"},{"speaker":null,"text":"На пятый день я проснулся от того, что на кухне шло совещание. Энни вела пятиминутку, пока я спал: дежурства, продукты, кто кому должен.","id":"t8"},{"speaker":"gwen","text":"— У нас тут диктатура.","id":"t9"},{"speaker":"annie","text":"— У нас порядок. Ты просто отвыкла.","id":"t10"},{"speaker":null,"text":"Я должен был разогнать. Вместо этого сел в дверях и слушал: она расставляла то, что я начал расставлять, лучше меня.","id":"t11"},{"speaker":"hero","text":"— Энни. Ты старшая по дому.","id":"t12"},{"speaker":"annie","text":"— Я знаю. Я ждала, когда ты это скажешь.","id":"t13"},{"speaker":null,"text":"Она повесила рядом вторую доску: «что {имя} должен каждому из нас». Двадцать девять строк, из них двадцать две про еду.","id":"t14"},{"speaker":"felicia","text":"— Девочка, ты страшнее смотрителя.","id":"t15"},{"speaker":"annie","text":"— Смотритель — это должность. А порядок — это я.","id":"t16"},{"speaker":null,"text":"Больше всего я боялся, что она заменит меня в этом доме. И записал это в колонку «страх». Под своей фамилией.","set":[{"var":"быт_энни","op":"set","value":"1"},{"var":"порядок","op":"add","value":"1"}],"goto":"sc_adapt:t1","id":"t17"}]},{"id":"sc_a_felicia","name":"Деньги","bg":"assets/street.webp","weather":"snow","cast":[],"steps":[{"speaker":null,"text":"Первым пропал шоколад. Не из дома — из «Монетки»: плитка легла в карман, и я это видел.","id":"t1"},{"speaker":"hero","text":"— Фелиция.","id":"t2"},{"speaker":"felicia","text":"— Я не украла. Я одолжила у человека, который не заметит.","id":"t3"},{"speaker":null,"text":"Мы вернулись в магазин. Она держала шоколад на кассе и улыбалась так, будто её ведут на казнь, а не платить.","id":"t4"},{"speaker":"hero","text":"— Платишь сам. И следи, чтобы тебе это не вышло дороже.","id":"t5"},{"speaker":"felicia","text":"— Тебе — восемьдесят рублей. Мне — ничего. Это несправедливо.","id":"t6"},{"speaker":null,"text":"Я записал в доску: «Фелиция. Не воровка — без денег. Причина: не знает цены. Решение: свои».","id":"t7"},{"speaker":null,"text":"В субботу мы вынесли на улицу бабушкино: сервант, три табурета, ковёр, который жалко, и пять килограммов банок, которые не жалко.","id":"t8"},{"speaker":null,"text":"За два дня она продала всё. Ковёр — за девятьсот, банки — за четыреста, сервант — за две тысячи, «потому что у людей в Тюмени есть всё, кроме рук».","id":"t9"},{"speaker":"felicia","text":"— Две тысячи четыреста в кармане. Мальчик. Это мои деньги.","id":"t10"},{"speaker":"hero","text":"— Не «мальчик». {имя}.","id":"t11"},{"speaker":"felicia","text":"— Хорошо, {имя}. — Она назвала меня по имени и впервые за неделю не попыталась меня облапошить.","id":"t12"},{"speaker":null,"text":"Она взяла себе правило: чужое не брать, своё — считать. Я написал это на доске, а она поставила рядом крестик, как ставят на корабле.","id":"t13"},{"speaker":"gwen","text":"— Она у нас тоже крала?","id":"t14"},{"speaker":"felicia","text":"— Я вела учёт, деточка. Твои носки — мои. Пока ты не поставила им цену.","id":"t15"},{"speaker":null,"text":"На доске появилась колонка «кошелёк»: у каждой столько, сколько она заработала. Я заплатил за всех, а она заставила записать долг — и записала мой первым.","id":"t16"},{"speaker":null,"text":"«Ей нужен не замок, а своя дверь», — написал я и наконец поставил ей галочку за то, чего она сама не заметила.","set":[{"var":"быт_фелиция","op":"set","value":"1"},{"var":"порядок","op":"add","value":"1"}],"goto":"sc_adapt:t1","id":"t17"}]},{"id":"sc_a_tenten","name":"Задания","bg":"assets/yard.webp","weather":"snow","cast":[],"steps":[{"speaker":null,"text":"Тентен на второй день начала меня ломать. Не в драке — в быту.","id":"t1"},{"speaker":"tenten","text":"— У тебя дверь висит криво. Сними, я поставлю.","id":"t2"},{"speaker":null,"text":"Она сняла дверь, выставила её по уровню — уровня у меня нет, она выставила на глаз — и повесила обратно за двадцать минут.","id":"t3"},{"speaker":"hero","text":"— Откуда?","id":"t4"},{"speaker":"tenten","text":"— Меня этому не учили. Мне просто скучно без работы.","id":"t5"},{"speaker":null,"text":"К вечеру у меня на столе лежал список «задания», который я составил, сам не заметив: полка, плинтус, замок, табурет, вынести, принести, прибить, подтянуть.","id":"t6"},{"speaker":"tenten","text":"— Восемь. — Она прочитала и сгрызла ноготь. — Мне можно пять.","id":"t7"},{"speaker":"hero","text":"— Можно шесть. И не торгуйся со мной.","id":"t8"},{"speaker":null,"text":"Она сделала шесть за день и попросила остаток. Я выдавал ей задания как паёк и ловил себя на том, что обращаю человека в инструмент.","id":"t9"},{"speaker":null,"text":"На пятый день я нашёл её во дворе, на турнике у «Монетки»: она крутилась, а вокруг стояли четверо мужиков и считали.","id":"t10"},{"speaker":"felicia","text":"— Сорок первый. Сорок второй.","id":"t11"},{"speaker":null,"text":"Я хотел крикнуть «иди домой». Не крикнул. Подошёл, встал на скамейку рядом и начал считать сорок три.","id":"t12"},{"speaker":"tenten","text":"— Ты чего?","id":"t13"},{"speaker":"hero","text":"— Не по заданию.","id":"t14"},{"speaker":null,"text":"После этого я вычеркнул слово «задания» и написал сверху: «дело дома: кто хочет — делает, кто не хочет — тоже, но потом».","id":"t15"},{"speaker":"tenten","text":"— Вот так и надо было сразу. — Она подтянулась ещё раз и добавила: — И полку ты не додал.","id":"t16"},{"speaker":null,"text":"На доске напротив неё я написал: «ей нужна миссия. дай ей нормальную» — и в первую очередь себе.","set":[{"var":"быт_тентен","op":"set","value":"1"},{"var":"порядок","op":"add","value":"1"}],"goto":"sc_adapt:t1","id":"t17"}]},{"id":"sc_sick","name":"Он заболел","bg":"assets/night.webp","weather":"none","cast":[],"steps":[{"speaker":null,"text":"На седьмой день я проснулся и не смог встать.","id":"t1"},{"speaker":null,"text":"Сначала 36,8, потом 38,2. Горло как наждак, и доска передвигалась, когда я пытался её прочитать.","id":"t2"},{"speaker":"hero","text":"— Пятиминутка. Надо… — Я не договорил.","id":"t3"},{"speaker":"gwen","text":"— Лежи, командир. Впервые за неделю — просто лежи.","id":"t4"},{"speaker":null,"text":"Дом развалился за четыре часа: ключи не нашли, мусор не вынесли, кашу испортили, и Энни ушла в себя, потому что считать стало некому.","id":"t5"},{"speaker":"annie","text":"— Без тебя мы не умеем.","id":"t6"},{"speaker":"mikasa","text":"— Умеем. Мы умели и до него.","id":"t7"},{"speaker":null,"text":"Они принесли мне йогурт, варенье, бабушкин мёд и чашку, из которой в этом доме пьют только за болящими.","id":"t8"},{"speaker":"felicia","text":"— Мальчик, если ты сдохнешь, я заберу диван.","id":"t9"},{"speaker":"sakura","text":"— Тс-с. У него температура, он будет говорить глупости.","id":"t10"},{"speaker":null,"text":"Тентен прибила мне поднос из фанеры, чтобы есть сидя. Это было единственное полезное действие за день, сделанное без моей команды.","id":"t11"},{"speaker":null,"text":"Вечером Гвен зачитала моё расписание так, как я его писал, только путая имена. Я хохотал, потом кашлял, потом снова хохотал.","id":"t12"},{"speaker":"gwen","text":"— «Двадцать три — пятиминутка». «Гвен не каркает». «Энни не трогать».","id":"t13"},{"speaker":"hero","text":"— Это я правильно написал.","id":"t14"},{"speaker":null,"text":"Ночью я сорвал доску со стены, чтобы она не скрипела, и не повесил обратно.","id":"t15"},{"speaker":null,"text":"Утром её повесили они: шесть галочек и одна лишняя строчка внизу — «{имя} тоже человек».","id":"t16"},{"speaker":"hero","text":"— Это зачем?","id":"t17"},{"speaker":"annie","text":"— Чтобы не забыл. Ты про всех всё знаешь, а про себя — только график.","id":"t18"},{"speaker":null,"text":"К вечеру температура упала. Я понял две вещи: причина не в системе и дом — не мой.","id":"t19"},{"speaker":null,"text":"И ещё: к тому моменту, когда шов попросит одного, я буду думать уже не о том, как это расписать, а о том, как это пережить.","id":"t20"}]},{"id":"sc_week","name":"Семь дней","bg":"assets/kitchen.webp","weather":"none","cast":[],"steps":[{"speaker":null,"text":"Неделя прошла так, будто мы всегда жили вместе. Почти.","id":"t1"},{"speaker":"felicia","text":"— Мальчик, у нас закончилась соль. И твоя удача. Я проверила.","goto":"sc_week:t3","id":"t2"},{"speaker":"hero","text":"— Соль куплю. Удачу не обещаю.","goto":"sc_week:t4","id":"t3"},{"speaker":null,"text":"В ванной висели шесть зубных щёток. Седьмая, моя, стояла отдельно — так я старался быть вежливым.","goto":"sc_week:t5","id":"t4"},{"speaker":"sakura","text":"— Кто съел последний йогурт? Я не для того варила рис на всех!","goto":"sc_week:t6","id":"t5"},{"speaker":"annie","text":"— Он был вкусный.","goto":"sc_week:t7","id":"t6"},{"speaker":"sakura","text":"— ...Ладно.","goto":"sc_week:t8","id":"t7"},{"speaker":null,"text":"Микаса мыла посуду так, будто это была тренировка. Гвен смотрела в потолок и комментировала. Тентен починила дверцу шкафа, дверцу холодильника и одну лампочку.","goto":"sc_week:t9","id":"t8"},{"speaker":"tenten","text":"— У тебя всё разваливается. Мне тут нравится.","goto":"sc_week:t10","id":"t9"},{"speaker":"gwen","text":"— А мне нравится, что тут никто не умирает. Тьфу-тьфу, конечно.","goto":"sc_week:t11","id":"t10"},{"speaker":"hero","text":"— Не каркай.","goto":"sc_week:t11c1","id":"t11"},{"speaker":"tenten","text":"— Ты опять не был на парах.","id":"t11c1"},{"speaker":"hero","text":"— У меня практика.","id":"t11c2"},{"speaker":"annie","text":"— У тебя шесть человек. Это не практика, это вахта.","id":"t11c3"},{"speaker":null,"text":"Я был уверен, что всё держится на доске. За неделю доска падала трижды, и каждый раз её вешали обратно без меня.","id":"t11c4"},{"speaker":null,"text":"Вечером мы смотрели телевизор — шесть девушек и я — и спорили, что хуже: реклама или новости.","goto":"sc_week:t13","id":"t12"},{"speaker":"mikasa","text":"— В новостях говорят про Тюмень. Каждый день.","goto":"sc_week:t14","id":"t13"},{"speaker":"hero","text":"— Это не странно. Это Тюмень.","goto":"sc_week:t15","id":"t14"},{"speaker":null,"text":"На седьмой день бабушкина тетрадь лежала на столе, и все шесть смотрели на неё, а не на меня.","goto":"sc_week:t16","id":"t15"},{"speaker":"felicia","text":"— Ну что, смотритель. Куда нас поведёшь?","goto":"sc_week:t17","id":"t16"},{"speaker":"hero","text":"— Туда, где вам что-то напоминает дом.","goto":"sc_week:t18","id":"t17"},{"speaker":null,"text":"Это было лучшее решение из тех, что я принял за неделю.","id":"t18"},{"speaker":"annie","text":"— Есть вопрос. — Энни посмотрела на доску. — Что делать, если ты решишь за нас?","id":"t18c1"},{"speaker":"hero","text":"— Не буду.","id":"t18c2"},{"speaker":"mikasa","text":"— Ты уже один раз решил. — Микаса кивнула на график в ванной. — Это было хорошо. Но ты решил.","id":"t18c3"},{"speaker":null,"text":"На доске было шесть галочек, и я понимал, что это не про порядок. Это про то, что семь человек неделю прожили в одной квартире и никого не потеряли.","if":"порядок >= 6","id":"t18c4"}]},{"id":"sc_hub","name":"Кого ведём","bg":"assets/hall.webp","weather":"none","cast":[],"steps":[{"speaker":null,"text":"Бабушкин список: шесть строк, шесть адресов. Пока не пройдены все шесть порогов, шов не отпустит никого.\nКого ведём к порогу?","choices":[{"text":"Мост","if":"порог_гвен == 0","goto":"sc_gwen:t1"},{"text":"Крыши и замки","if":"порог_фелиция == 0","goto":"sc_felicia:t1"},{"text":"Стена","if":"порог_микаса == 0","goto":"sc_mikasa:t1"},{"text":"Лёд","if":"порог_энни == 0","goto":"sc_annie:t1"},{"text":"Костёр","if":"порог_сакура == 0","goto":"sc_sakura:t1"},{"text":"Кузня","if":"порог_тентен == 0","goto":"sc_tenten:t1"}],"gotoIf":[{"when":"порог_гвен > 0 && порог_фелиция > 0 && порог_микаса > 0 && порог_энни > 0 && порог_сакура > 0 && порог_тентен > 0","goto":"sc_evening:t1"}],"id":"t1"}],"card":false},{"id":"sc_gwen","name":"Мост","bg":"assets/bridge.webp","weather":"snow","cast":[],"steps":[{"speaker":null,"text":"Порог Гвен оказался наверху. Конечно, наверху.","id":"t1"},{"speaker":"gwen","text":"— Мне нужно туда, где ветер. Мост подойдёт.","id":"t2"},{"speaker":"hero","text":"— У нас есть мост Влюблённых. И Дом Печати.","id":"t3"},{"speaker":"gwen","text":"— Мост. Идём на мост.","id":"t4"},{"speaker":null,"text":"Она шла по бордюру, как по канату, и говорила без остановки. Про Бруклин, про группу, про три комплекта барабанных палочек, которые остались там.","id":"t5"},{"speaker":"gwen","text":"— Знаешь, что самое дурацкое? Про меня в моём мире написали, что я умерла. Все с этим живут. А я — живу. Смешно?","id":"t6"},{"speaker":"hero","text":"— Не очень.","id":"t7"},{"speaker":"gwen","text":"— Совсем не смешно, да.","id":"t8"},{"speaker":null,"text":"На середине моста воздух стал другим — как перед грозой.","id":"t9"},{"speaker":"gwen","text":"— Вот. Порог. Если я шагну — вернусь домой. И вы меня забудете.","id":"t10"},{"speaker":"hero","text":"— Я не забуду.","id":"t11"},{"speaker":"gwen","text":"— Ты — может быть.","id":"t12"},{"speaker":"gwen","text":"— О. — Гвен легко запрыгнула на перила и удержалась двумя пальцами. — Оно вернулось. — Она смотрела на свои руки, как на чужие.","id":"t12a","goto":"sc_gwen:t13"},{"speaker":null,"text":"","choices":[{"text":"Иди домой. Тебя там ждут.","goto":"sc_gwen:t14"},{"text":"Останься. Пожалуйста.","goto":"sc_gwen:t16"},{"text":"Решай сама.","goto":"sc_gwen:t18"}],"id":"t13"},{"speaker":"gwen","text":"— Ты прав. — Она улыбнулась. — Нелепо, но ты прав. — И шагнула в воздух, и мост на секунду стал белым.","set":[{"var":"порог_гвен","op":"set","value":"1"}],"goto":"sc_gwen:t15","id":"t14"},{"speaker":null,"text":"Снег пошёл снова. Я стоял один на середине моста и говорил себе: «Я помню. Я обещал».","goto":"sc_hub:t1","id":"t15"},{"speaker":"gwen","text":"— Хорошо. — Она выдохнула. — Только знай: я остаюсь не потому, что мне некуда. А потому, что есть куда.","set":[{"var":"порог_гвен","op":"set","value":"2"}],"goto":"sc_gwen:t17","id":"t16"},{"speaker":null,"text":"Обратно мы шли, и она держалась за мой рукав. Не за руку — за рукав. Так проще притворяться, что это случайно.","goto":"sc_hub:t1","id":"t17"},{"speaker":"gwen","text":"— Вот как. — Она посмотрела на воду. — Тогда я скажу сама. Там, откуда я пришла, меня похоронили. Здесь — нет. — И шагнула.","set":[{"var":"порог_гвен","op":"set","value":"1"}],"goto":"sc_gwen:t19","id":"t18"},{"speaker":null,"text":"Только потом я понял: она выбрала не «домой». Она выбрала «не здесь».","goto":"sc_hub:t1","id":"t19"}]},{"id":"sc_felicia","name":"Крыши и замки","bg":"assets/roof.webp","weather":"snow","cast":[],"steps":[{"speaker":null,"text":"Порог Фелиции оказался внизу, в замке.","id":"t1"},{"speaker":"felicia","text":"— Мне нужны крыши. И замок. Желательно чужой.","id":"t2"},{"speaker":"hero","text":"— Есть ломбард на Цветном. И крыша моего дома.","id":"t3"},{"speaker":"felicia","text":"— Ты начинаешь мне нравиться.","id":"t4"},{"speaker":null,"text":"Подъездный замок она открыла за четыре секунды. Мой собственный замок.","id":"t5"},{"speaker":"felicia","text":"— Привычка. Не смотри так.","id":"t6"},{"speaker":null,"text":"На крыше она вдруг перестала улыбаться.","id":"t7"},{"speaker":"felicia","text":"— Знаешь, что я делаю, когда страшно? Считаю выходы. Тут их два, пожарная лестница, и один — через тебя.","id":"t8"},{"speaker":"hero","text":"— Через меня?","id":"t9"},{"speaker":"felicia","text":"— Ты единственный, кто меня тут не боится. Это редкая вещь.","id":"t10"},{"speaker":null,"text":"Ветер поднял снег, и в нём блеснула тонкая полоса — как трещина в воздухе.","id":"t11"},{"speaker":"felicia","text":"— Вот он. Если пройду — вернусь к своим делам, к папе, к городу. — Она посмотрела на меня. — А если останусь, стану обычной девчонкой, которая не умеет открывать чужие замки.","id":"t12"},{"speaker":null,"text":"Фелиция провела рукой по замку пожарной лестницы, и тот открылся сам.","id":"t11a"},{"speaker":"felicia","text":"— Вот. Вернулось. — Она коротко, зло засмеялась. — Как раз тогда, когда я решила уйти.","id":"t11b","goto":"sc_felicia:t13"},{"speaker":null,"text":"","choices":[{"text":"Иди домой. Тебя там ждут.","goto":"sc_felicia:t14"},{"text":"Останься. Пожалуйста.","goto":"sc_felicia:t16"},{"text":"Решай сама.","goto":"sc_felicia:t18"}],"id":"t13"},{"speaker":"felicia","text":"— Ладно. — Она улыбнулась, и улыбка была настоящая. — Спасибо, что сказал вслух. — И шагнула в полосу, как в дверь.","set":[{"var":"порог_фелиция","op":"set","value":"1"}],"goto":"sc_felicia:t15","id":"t14"},{"speaker":null,"text":"Полоса сомкнулась. Я стоял на крыше, и снег ложился мне на плечи ровно, без ветра.","goto":"sc_hub:t1","id":"t15"},{"speaker":"felicia","text":"— Хочешь, чтобы я осталась? — Она прищурилась. — Смотри, я запомню. — И осталась.","set":[{"var":"порог_фелиция","op":"set","value":"2"}],"goto":"sc_felicia:t17","id":"t16"},{"speaker":null,"text":"Мы спустились вниз, и она всю дорогу считала вслух: «Дверь, лестница, окно, ты».","goto":"sc_hub:t1","id":"t17"},{"speaker":"felicia","text":"— Сама? — Она хмыкнула. — Тогда сама. — И шагнула, и обернулась. — Всё-таки жаль. Ты был бы хорошим напарником.","set":[{"var":"порог_фелиция","op":"set","value":"1"}],"goto":"sc_felicia:t19","id":"t18"},{"speaker":null,"text":"Я ещё долго стоял на крыше. Снег шёл, и город внизу жил своей жизнью, в которую она не захотела.","goto":"sc_hub:t1","id":"t19"}]},{"id":"sc_mikasa","name":"Стена","bg":"assets/wall.webp","weather":"snow","cast":[],"steps":[{"speaker":null,"text":"Порог Микасы был из камня.","id":"t1"},{"speaker":"mikasa","text":"— Здесь есть стена?","id":"t2"},{"speaker":"hero","text":"— Есть старый острог. И стена на набережной.","id":"t3"},{"speaker":null,"text":"Она шла быстро, и я еле успевал.","id":"t4"},{"speaker":"mikasa","text":"— Этот шарф дал мне один человек.","id":"t5"},{"speaker":"hero","text":"— Который тебе дорог?","id":"t6"},{"speaker":"mikasa","text":"— Которого больше нет.","id":"t7"},{"speaker":null,"text":"У стены снег шёл так густо, что города не стало.","id":"t8"},{"speaker":"mikasa","text":"— Если я вернусь, я вернусь туда, где всё уже случилось. — Она помолчала. — Здесь я просто девушка, которая слишком быстро ходит.","id":"t9"},{"speaker":"hero","text":"— Здесь ты можешь не воевать.","id":"t10"},{"speaker":"mikasa","text":"— Я не умею не воевать.","id":"t11"},{"speaker":null,"text":"Микаса сорвалась с места и вернулась через три секунды. Снег за ней встал стеной.","id":"t11a"},{"speaker":"mikasa","text":"— Снова могу. — Она посмотрела на свои руки. — И всё равно медленно.","id":"t11b","goto":"sc_mikasa:t12"},{"speaker":null,"text":"","choices":[{"text":"Иди домой. Тебя там ждут.","goto":"sc_mikasa:t13"},{"text":"Останься. Пожалуйста.","goto":"sc_mikasa:t15"},{"text":"Решай сама.","goto":"sc_mikasa:t17"}],"id":"t12"},{"speaker":"mikasa","text":"— Я вернусь. — Она сказала это ровно, как приказ. — Там меня ждут. — И шагнула в стену, и стена приняла её без звука.","set":[{"var":"порог_микаса","op":"set","value":"1"}],"goto":"sc_mikasa:t14","id":"t13"},{"speaker":null,"text":"На снегу остался красный шарф. Я поднял его. Он был тёплый.","goto":"sc_hub:t1","id":"t14"},{"speaker":"mikasa","text":"— Хорошо. — Она посмотрела на меня. — Тогда я буду ходить медленно. — И это было почти обещание.","set":[{"var":"порог_микаса","op":"set","value":"2"}],"goto":"sc_mikasa:t16","id":"t15"},{"speaker":null,"text":"Мы шли обратно, и она впервые не смотрела по сторонам. Только вперёд.","goto":"sc_hub:t1","id":"t16"},{"speaker":"mikasa","text":"— Сама. — Она кивнула. — Так честнее. — И шагнула в стену и не обернулась.","set":[{"var":"порог_микаса","op":"set","value":"1"}],"goto":"sc_mikasa:t18","id":"t17"},{"speaker":null,"text":"Я не знал, правильно ли это. Я вообще ничего не знал в тот вечер.","goto":"sc_hub:t1","id":"t18"}]},{"id":"sc_annie","name":"Лёд","bg":"assets/ice.webp","weather":"snow","cast":[],"steps":[{"speaker":null,"text":"Энни сказала одно слово: «лёд».","id":"t1"},{"speaker":"hero","text":"— У нас есть каток. И озеро. Правда, сейчас оно твёрдое.","id":"t2"},{"speaker":"annie","text":"— Пойдёт.","id":"t3"},{"speaker":null,"text":"Она вышла на лёд и просто поехала. Без разбега, без эмоций — как будто так и надо.","id":"t4"},{"speaker":"annie","text":"— В моём мире я была оружием. Девочка, которую боятся.","id":"t5"},{"speaker":"hero","text":"— А здесь?","id":"t6"},{"speaker":"annie","text":"— Здесь я ем мороженое в девять утра, и никто не просит меня убивать. — Она прищурилась. — Это подозрительно.","id":"t7"},{"speaker":"hero","text":"— Это Тюмень.","id":"t8"},{"speaker":"annie","text":"— Это лучше, чем Тюмень.","id":"t9"},{"speaker":null,"text":"Лёд тонко звенел, и в звоне был другой звук — будто где-то открыли окно.","id":"t10"},{"speaker":"annie","text":"— Порог. Я чувствую. Если уйду — снова стану тем, чем была.","id":"t11"},{"speaker":null,"text":"Энни коснулась борта, и под её пальцами выступил кристалл — тонкий, как стекло.","id":"t11a"},{"speaker":"annie","text":"— Значит, оно всё ещё во мне. Спрятано.","id":"t11b","goto":"sc_annie:t12"},{"speaker":null,"text":"","choices":[{"text":"Иди домой. Тебя там ждут.","goto":"sc_annie:t13"},{"text":"Останься. Пожалуйста.","goto":"sc_annie:t15"},{"text":"Решай сама.","goto":"sc_annie:t17"}],"id":"t12"},{"speaker":"annie","text":"— Тогда я пойду. — Она сошла со льда, и лёд под ней не треснул. — Не провожай.","set":[{"var":"порог_энни","op":"set","value":"1"}],"goto":"sc_annie:t14","id":"t13"},{"speaker":null,"text":"Она ушла в полосу света, как в дверь, и в катке стало очень тихо.","goto":"sc_hub:t1","id":"t14"},{"speaker":"annie","text":"— Ладно. — Она сказала это так, будто делала одолжение. — Но мороженое покупаешь ты.","set":[{"var":"порог_энни","op":"set","value":"2"}],"goto":"sc_annie:t16","id":"t15"},{"speaker":null,"text":"Мы просидели на трибуне до закрытия. Она молчала, но не уходила.","goto":"sc_hub:t1","id":"t16"},{"speaker":"annie","text":"— Сама. — Она усмехнулась. — Наконец-то кто-то не лезет. — И шагнула.","set":[{"var":"порог_энни","op":"set","value":"1"}],"goto":"sc_annie:t18","id":"t17"},{"speaker":null,"text":"Я остался у борта, и лёд медленно перестал звенеть.","goto":"sc_hub:t1","id":"t18"}]},{"id":"sc_sakura","name":"Костёр","bg":"assets/fire.webp","weather":"snow","cast":[],"steps":[{"speaker":null,"text":"Сакура сказала, что ей нужен огонь и вода одновременно.","id":"t1"},{"speaker":"sakura","text":"— Термальные источники?! У вас есть термальные источники?!","id":"t2"},{"speaker":"hero","text":"— Верхний Бор. Сорок минут на автобусе.","id":"t3"},{"speaker":"sakura","text":"— На чём?","id":"t4"},{"speaker":"hero","text":"— На автобусе.","id":"t5"},{"speaker":null,"text":"В автобусе она рассказывала про команду: про мальчика в оранжевом, который вечно лез первым, про то, как училась быть сильной.","id":"t6"},{"speaker":"sakura","text":"— Меня считали бесполезной. Потом полезной. Потом опять. А я просто хотела, чтобы все вернулись домой.","id":"t7"},{"speaker":"hero","text":"— И как?","id":"t8"},{"speaker":"sakura","text":"— Не все вернулись.","id":"t9"},{"speaker":null,"text":"У источника был пар, снег и красный свет от костра, который она развела двумя камнями.","id":"t10"},{"speaker":"sakura","text":"— Вот он. Я чувствую, как оттуда пахнет домом. Раменом и пылью.","id":"t11"},{"speaker":null,"text":"Сакура приложила ладонь к костру, и огонь вырос до её роста.","id":"t11a"},{"speaker":"sakura","text":"— Ох. — Она засмеялась. — Я скучала.","id":"t11b","goto":"sc_sakura:t12"},{"speaker":null,"text":"","choices":[{"text":"Иди домой. Тебя там ждут.","goto":"sc_sakura:t13"},{"text":"Останься. Пожалуйста.","goto":"sc_sakura:t15"},{"text":"Решай сама.","goto":"sc_sakura:t17"}],"id":"t12"},{"speaker":"sakura","text":"— Вернусь. — Она вытерла руки о штаны. — Там без меня не справятся. — И улыбнулась так, что я поверил.","set":[{"var":"порог_сакура","op":"set","value":"1"}],"goto":"sc_sakura:t14","id":"t13"},{"speaker":null,"text":"Костёр догорел. Я сидел у воды и слушал, как шумит лес — так же, как когда мы пришли.","goto":"sc_hub:t1","id":"t14"},{"speaker":"sakura","text":"— Остаться? — Она посмотрела на меня, потом на костёр. — Тогда я буду кормить тебя каждое утро. И это не шутка.","set":[{"var":"порог_сакура","op":"set","value":"2"}],"goto":"sc_sakura:t16","id":"t15"},{"speaker":null,"text":"Обратно мы шли пешком. Автобус не пришёл, и это было лучше любого автобуса.","goto":"sc_hub:t1","id":"t16"},{"speaker":"sakura","text":"— Сама? — Она задумалась. — Ладно. — И шагнула, и обернулась. — Ешь нормально, слышишь?","set":[{"var":"порог_сакура","op":"set","value":"1"}],"goto":"sc_sakura:t18","id":"t17"},{"speaker":null,"text":"Я кивнул. Я всегда киваю, когда нечего сказать.","goto":"sc_hub:t1","id":"t18"}]},{"id":"sc_tenten","name":"Кузня","bg":"assets/forge.webp","weather":"none","cast":[],"steps":[{"speaker":null,"text":"Тентен сказала: «мне нужна кузня». В Тюмени кузня нашлась.","id":"t1"},{"speaker":"tenten","text":"— Настоящая? С наковальней?","id":"t2"},{"speaker":"hero","text":"— С наковальней. Мужик на Комарово делает ножи.","id":"t3"},{"speaker":"tenten","text":"— Ножи. Хорошо.","id":"t4"},{"speaker":null,"text":"В кузне она впервые за всё время улыбнулась. Не мне — наковальне.","id":"t5"},{"speaker":"tenten","text":"— В моей истории я всегда была второй. Та, кто подаёт оружие. Кого забывают нарисовать в финале.","id":"t6"},{"speaker":"hero","text":"— Это обидно.","id":"t7"},{"speaker":"tenten","text":"— Это честно. — Она взяла молоток. — Зато я умею делать вещи, которые не ломаются.","id":"t8"},{"speaker":null,"text":"Она положила на наковальню свиток, и свиток засветился. В воздухе запахло металлом и пылью.","id":"t9"},{"speaker":"tenten","text":"— Порог. Если вернусь — снова буду второй. Если останусь — перестану быть даже второй. Стану никем из этого города.","id":"t10"},{"speaker":"hero","text":"— Или просто Тентен.","id":"t11"},{"speaker":"tenten","text":"— ...Это неожиданно приятно звучит.","id":"t12"},{"speaker":null,"text":"Свиток на наковальне раскрылся сам, и из него вышел короткий клинок.","id":"t12a"},{"speaker":"tenten","text":"— Работает. — Она сказала это тихо, будто боялась спугнуть.","id":"t12b","goto":"sc_tenten:t13"},{"speaker":null,"text":"","choices":[{"text":"Иди домой. Тебя там ждут.","goto":"sc_tenten:t14"},{"text":"Останься. Пожалуйста.","goto":"sc_tenten:t16"},{"text":"Решай сама.","goto":"sc_tenten:t18"}],"id":"t13"},{"speaker":"tenten","text":"— Вернусь. — Она повесила молоток на место. — Там мой свиток. И моя команда. — И шагнула, и молоток остался висеть.","set":[{"var":"порог_тентен","op":"set","value":"1"}],"goto":"sc_tenten:t15","id":"t14"},{"speaker":null,"text":"Я ещё постоял в кузне, слушая, как остывает железо.","goto":"sc_hub:t1","id":"t15"},{"speaker":"tenten","text":"— Останусь. — Она протянула мне руку. — Будешь держать заготовку. Осторожно, горячо.","set":[{"var":"порог_тентен","op":"set","value":"2"}],"goto":"sc_tenten:t17","id":"t16"},{"speaker":null,"text":"Мы вышли из кузни в снег, и она всю дорогу объясняла, чем ковка клинка отличается от ковки гвоздя.","goto":"sc_hub:t1","id":"t17"},{"speaker":"tenten","text":"— Сама. — Она кивнула. — Правильно. — И шагнула. — Скажи там... в общем, ничего не говори.","set":[{"var":"порог_тентен","op":"set","value":"1"}],"goto":"sc_tenten:t19","id":"t18"},{"speaker":null,"text":"Я не сказал. Я вообще молчал всю дорогу домой.","goto":"sc_hub:t1","id":"t19"}]},{"id":"sc_evening","name":"Набережная","bg":"assets/river.webp","weather":"snow","cast":[],"steps":[{"speaker":null,"text":"К вечеру шов стал виден: тонкая светлая полоса над Турой, как трещина в стекле.","id":"t1"},{"speaker":null,"text":"Бабушка писала: «Шов закроется, когда вахта будет принята. Не тяни до утра — утром он заберёт смотрителя».","id":"t2"},{"speaker":null,"text":"Мы пришли на набережную все, кто ещё остался.","id":"t3"},{"speaker":"gwen","text":"— Я думала, переезд в другой мир — это драматично. А оказалось: маршрутка, пельмени, шкаф. Я почти счастлива.","if":"порог_гвен == 2","id":"t4"},{"speaker":"felicia","text":"— Обещаю не воровать. — Пауза. — Много.","if":"порог_фелиция == 2","id":"t5"},{"speaker":"mikasa","text":"— Ты ходишь медленно. Я подожду.","if":"порог_микаса == 2","id":"t6"},{"speaker":"annie","text":"— Тут мороженое продают круглый год. Я проверила. Это лучший город на свете.","if":"порог_энни == 2","id":"t7"},{"speaker":"sakura","text":"— Я сварила рамен из того, что нашла. Он ужасный. Я горжусь им.","if":"порог_сакура == 2","id":"t8"},{"speaker":"tenten","text":"— Я починила твой чайник. И дверь. И половину кухни.","if":"порог_тентен == 2","id":"t9"},{"speaker":"gwen","text":"— Знаешь, за что я зацепилась? За то, что ты всех по именам помнишь. Я бы не смогла.","if":"быт_гвен >= 1","id":"t9c1"},{"speaker":"hero","text":"— Я и про себя не всё помню. — Я посмотрел на реку. — Расписание-то я в итоге сорвал.","if":"порядок >= 6","id":"t9c2"},{"speaker":"hero","text":"— У меня не было плана на этот вечер.","id":"t10"},{"speaker":null,"text":"Полоса над рекой стала ярче. Время выходило.","id":"t11"},{"speaker":"hero","text":"— Пойдём домой. Надо решать.","id":"t12"}]},{"id":"sc_final","name":"Вахта","bg":"assets/seam.webp","weather":"snow","cast":[],"steps":[{"speaker":null,"text":"Дома шов стоял в дверях, как свет из другой комнаты.","id":"t1"},{"speaker":null,"text":"Ни одна не сказала «я останусь». Я закрыл дверь, сел на пол в коридоре и достал тетрадь.","if":"порог_гвен != 2 && порог_фелиция != 2 && порог_микаса != 2 && порог_энни != 2 && порог_сакура != 2 && порог_тентен != 2","goto":"sc_final:t23","id":"t2"},{"speaker":"hero","text":"— Есть правило. Один остаётся навсегда. Остальные успевают уйти до утра.","id":"t3"},{"speaker":"gwen","text":"— Я останусь. — Гвен спрыгнула с подоконника. — У меня там всё уже случилось. А тут ещё нет.","if":"порог_гвен == 2","id":"t4"},{"speaker":"felicia","text":"— Я останусь. Впервые в жизни мне не хочется уходить до утра.","if":"порог_фелиция == 2","id":"t5"},{"speaker":"mikasa","text":"— Я останусь. Война от меня никуда не денется. А ты — можешь.","if":"порог_микаса == 2","id":"t6"},{"speaker":"annie","text":"— Я останусь. И это не жертва. Не смей думать, что это жертва.","if":"порог_энни == 2","id":"t7"},{"speaker":"sakura","text":"— Я останусь. Кто-то же должен кормить тебя нормально.","if":"порог_сакура == 2","id":"t8"},{"speaker":"tenten","text":"— Я останусь. Тут я не вторая. Тут я просто Тентен.","if":"порог_тентен == 2","id":"t9"},{"speaker":null,"text":"Шов ждал. Нужно было назвать одно имя.","choices":[{"text":"Взять Гвен за руку.","if":"порог_гвен == 2","goto":"sc_final:t11"},{"text":"Взять Фелицию за руку.","if":"порог_фелиция == 2","goto":"sc_final:t13"},{"text":"Взять Микасу за руку.","if":"порог_микаса == 2","goto":"sc_final:t15"},{"text":"Взять Энни за руку.","if":"порог_энни == 2","goto":"sc_final:t17"},{"text":"Взять Сакуру за руку.","if":"порог_сакура == 2","goto":"sc_final:t19"},{"text":"Взять Тентен за руку.","if":"порог_тентен == 2","goto":"sc_final:t21"},{"text":"Никого. Я приму вахту сам.","goto":"sc_final:t23"}],"id":"t10"},{"speaker":null,"text":"Остальные ушли до рассвета. По одной, через шов, не оборачиваясь.","goto":"sc_final:t12","id":"t11"},{"speaker":null,"text":"Гвен осталась. Она спит на шкафу — «на диване тесно» — и каждое утро проверяет, что мир ещё держится. Паутина больше её не держит. Зато держит кофе. А в шесть она надевает курьерскую куртку: у неё своя смена, свой эскалатор, который она теперь ненавидит открыто, и свои деньги в кармане.","end":true,"endTitle":"ВАХТА · ГВЕН","id":"t12"},{"speaker":null,"text":"Остальные ушли до рассвета. По одной, через шов, не оборачиваясь.","goto":"sc_final:t14","id":"t13"},{"speaker":null,"text":"Удача от неё ушла в ту же ночь: она потеряла перчатку, ключи и одну серёжку. — Зато нашла дом, — сказала Фелиция и больше к этому не возвращалась. Первые две тысячи четыреста она заработала на бабушкином серванте — и с тех пор чужого не взяла ни разу.","end":true,"endTitle":"ВАХТА · ФЕЛИЦИЯ","id":"t14"},{"speaker":null,"text":"Остальные ушли до рассвета. По одной, через шов, не оборачиваясь.","goto":"sc_final:t16","id":"t15"},{"speaker":null,"text":"Шарф остался. Шарф всегда остаётся. Микаса теперь ходит медленно — специально, чтобы я успевал. Иногда я успеваю. У двери ей постелили коврик, а шторы она закрывает сама: не от страха, а потому что так принято в доме.","end":true,"endTitle":"ВАХТА · МИКАСА","id":"t16"},{"speaker":null,"text":"Остальные ушли до рассвета. По одной, через шов, не оборачиваясь.","goto":"sc_final:t18","id":"t17"},{"speaker":null,"text":"Она больше не превращается в кристалл. Говорит, это лучшая новость за всю жизнь. В Тюмени мороженое продают круглый год — она проверила лично. Её доска висит в коридоре рядом с моей, и порядок на ней важнее, чем у меня: двадцать девять строк, из них двадцать две про еду.","end":true,"endTitle":"ВАХТА · ЭННИ","id":"t18"},{"speaker":null,"text":"Остальные ушли до рассвета. По одной, через шов, не оборачиваясь.","goto":"sc_final:t20","id":"t19"},{"speaker":null,"text":"Её руки больше не светятся. Зато в квартире всегда пахнет едой, и, кажется, это важнее любого лечения. Плита — её, и я к ней не подхожу. Даже за водой.","end":true,"endTitle":"ВАХТА · САКУРА","id":"t20"},{"speaker":null,"text":"Остальные ушли до рассвета. По одной, через шов, не оборачиваясь.","goto":"sc_final:t22","id":"t21"},{"speaker":null,"text":"Свиток больше не открывается. Зато на балконе появилась маленькая кузня, и соседи жалуются на стук. Хорошо, что не на запах. А во дворе она крутит турник до сорока, и я стою рядом и считаю. Уже не по заданию.","end":true,"endTitle":"ВАХТА · ТЕНТЕН","id":"t22"},{"speaker":null,"text":"Я принял вахту сам. Шов закрылся тихо, как закрывают дверь в комнату, где спят.","goto":"sc_final:t24","id":"t23"},{"speaker":null,"text":"Девушки вернулись в свои миры. Все, кто был. Помнят ли они Тюмень — не знаю. Я помню всех. Доска в коридоре ясная: шесть имён, шесть галочек и одна строчка внизу, написанная не мной — «смотритель тоже человек».","goto":"sc_final:t25","id":"t24"},{"speaker":null,"text":"Бабушка писала, что смотритель не может уйти. Зато может ждать. Иногда шов открывается снова. Я держу тетрадь открытой.","end":true,"endTitle":"ВАХТА · ТЫ","id":"t25"}]}],"baseUrl":"stories/peresylka/novels/kto-to-ostanetsya/","_builtin":"peresylka/novels/kto-to-ostanetsya"}]}]};
